		// dashboatd snippets function
	function event_Dashboard_snippet1( &$header, &$icon )
	{
		$header = "SET Compliance Overview";
$termId = isset($_SESSION["term_id"]) ? intval($_SESSION["term_id"]) : 1;



$sqlCompliance = "
WITH student_compliance_summary AS (
    SELECT
        student_id,
        COUNT(*) AS total_sets,
        COUNT(*) FILTER (WHERE has_taken_set = true) AS completed_sets
    FROM student_sets
    WHERE term_id = ".$termId."
    GROUP BY student_id
),
summary AS (
    SELECT
        COUNT(*) AS total_students,
        COUNT(*) FILTER (WHERE total_sets = completed_sets AND total_sets > 0) AS fully_compliant_count,
        COUNT(*) FILTER (WHERE completed_sets > 0 AND completed_sets < total_sets) AS partially_compliant_count,
        COUNT(*) FILTER (WHERE completed_sets = 0) AS non_compliant_count
    FROM student_compliance_summary
)
SELECT
    COALESCE(total_students, 0) AS total_students,
    COALESCE(fully_compliant_count, 0) AS fully_compliant_count,
    ROUND(COALESCE(fully_compliant_count * 100.0 / NULLIF(total_students, 0), 0), 2) AS fully_compliant_percentage,

    COALESCE(partially_compliant_count, 0) AS partially_compliant_count,
    ROUND(COALESCE(partially_compliant_count * 100.0 / NULLIF(total_students, 0), 0), 2) AS partially_compliant_percentage,

    COALESCE(non_compliant_count, 0) AS non_compliant_count,
    ROUND(COALESCE(non_compliant_count * 100.0 / NULLIF(total_students, 0), 0), 2) AS non_compliant_percentage
FROM summary";
$rs = DB::Query($sqlCompliance);
$data = $rs->fetchAssoc();

$total     = $data ? intval($data["total_students"]) : 0;
$fully     = $data ? intval($data["fully_compliant_count"]) : 0;
$partially = $data ? intval($data["partially_compliant_count"]) : 0;
$non       = $data ? intval($data["non_compliant_count"]) : 0;

$fullyPct     = $data ? $data["fully_compliant_percentage"] : 0;
$partiallyPct = $data ? $data["partially_compliant_percentage"] : 0;
$nonPct       = $data ? $data["non_compliant_percentage"] : 0;

// Unique ID para hindi mag-conflict kung may iba pang canvas
$chartId = "complianceChart_" . uniqid();

// 3. Render HTML at Chart.js
echo '
<div style="background: #ffffff; padding: 20px; border-radius: 8px; box-shadow: 0 1px 4px rgba(0,0,0,0.08); font-family: sans-serif;">
    <h4 style="margin: 0 0 15px 0; font-size: 16px; font-weight: 600; color: #2d3748;">

    
    <div style="display: flex; align-items: center; justify-content: space-around; flex-wrap: wrap; gap: 20px;">
        <!-- Canvas Container -->
        <div style="width: 220px; height: 220px; position: relative;">
            <canvas id="' . $chartId . '"></canvas>
        </div>

        <!-- Metric Details / Legend -->
        <div style="min-width: 200px;">
            <div style="margin-bottom: 12px; font-size: 13px;">
                <span style="display: inline-block; width: 10px; height: 10px; background: #10b981; border-radius: 50%; margin-right: 8px;"></span>
                <strong>Fully Compliant:</strong> ' . number_format($fully) . ' <span style="color: #6b7280;">(' . $fullyPct . '%)</span>
            </div>
            <div style="margin-bottom: 12px; font-size: 13px;">
                <span style="display: inline-block; width: 10px; height: 10px; background: #f59e0b; border-radius: 50%; margin-right: 8px;"></span>
                <strong>Partially Compliant:</strong> ' . number_format($partially) . ' <span style="color: #6b7280;">(' . $partiallyPct . '%)</span>
            </div>
            <div style="margin-bottom: 12px; font-size: 13px;">
                <span style="display: inline-block; width: 10px; height: 10px; background: #ef4444; border-radius: 50%; margin-right: 8px;"></span>
                <strong>Non-Compliant:</strong> ' . number_format($non) . ' <span style="color: #6b7280;">(' . $nonPct . '%)</span>
            </div>
            <hr style="border: 0; border-top: 1px solid #e5e7eb; margin: 10px 0;">
            <div style="font-size: 13px; color: #374151;">
                <strong>Total Evaluators:</strong> ' . number_format($total) . '
            </div>
        </div>
    </div>
</div>

<script src="https://cdn.jsdelivr.net/npm/chart.js"></script>
<script>
(function() {
    var ctx = document.getElementById("' . $chartId . '").getContext("2d");
    new Chart(ctx, {
        type: "doughnut",
        data: {
            labels: ["Fully Compliant", "Partially Compliant", "Non-Compliant"],
            datasets: [{
                data: [' . $fully . ', ' . $partially . ', ' . $non . '],
                backgroundColor: ["#10b981", "#f59e0b", "#ef4444"],
                hoverOffset: 4,
                borderWidth: 2,
                borderColor: "#ffffff"
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            cutout: "68%",
            plugins: {
                legend: { display: false }
            }
        }
    });
})();
</script>
';;
	}
